import { z } from "zod";
import {
  archiveScopeSchema,
  hexColorSchema,
  isoTimestampSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { projectKeySchema, slugSchema } from "./slug";

export const projectVisibilitySchema = z.enum(["private", "org", "public"]);
export const projectStatusSchema = z.enum(["active", "paused", "completed"]);

export const createProjectSchema = z.object({
  orgId: orgIdSchema,
  name: z.string().min(2).max(80),
  slug: slugSchema,
  key: projectKeySchema,
  description: z.string().max(2_000).nullable().default(null),
  visibility: projectVisibilitySchema.default("org"),
  leadId: userIdSchema.nullable().default(null),
  color: hexColorSchema.default("#6366f1"),
  targetDate: isoTimestampSchema.nullable().default(null),
});

export const updateProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  name: z.string().min(2).max(80).optional(),
  description: z.string().max(2_000).nullable().optional(),
  visibility: projectVisibilitySchema.optional(),
  status: projectStatusSchema.optional(),
  leadId: userIdSchema.nullable().optional(),
  color: hexColorSchema.optional(),
  targetDate: isoTimestampSchema.nullable().optional(),
});

export const archiveProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  archiveIssues: z.boolean().default(true),
});

export const listProjectsSchema = z
  .object({
    orgId: orgIdSchema,
    status: projectStatusSchema.optional(),
    query: z.string().max(200).optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

export type CreateProjectInput = z.infer<typeof createProjectSchema>;
export type UpdateProjectInput = z.infer<typeof updateProjectSchema>;
export type ArchiveProjectInput = z.infer<typeof archiveProjectSchema>;
export type ListProjectsInput = z.infer<typeof listProjectsSchema>;
/**
 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Creates a project once the plan still has room for one. The key is derived
 * from the name when the caller left it blank, so the issue numbering scheme
 * (`TF-12`) is never invented at the call site.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  return projectRepo.updateProject(input);
}

/**
 * Archiving a project cascades to its issues by default — leaving live issues
 * behind an archived project is the drift this flag exists to prevent.
 */
export async function archiveProject(
  actor: Actor,
  input: ArchiveProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const issuesArchived = input.archiveIssues
    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
    : 0;

  const archived = await projectRepo.archiveProject(
    input.orgId,
    input.projectId,
  );

  await emit("project.archived", {
    ...actorEnvelope(actor),
    projectId: archived.id,
    issuesArchived,
  });

  return archived;
}

/** Restore does not un-archive the issues: they are restored individually. */
export async function restoreProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));

  const restored = await projectRepo.restoreProject(orgId, projectId);

  await emit("project.restored", {
    ...actorEnvelope(actor),
    projectId: restored.id,
  });

  return restored;
}

export async function getProject(
  actor: Actor,
  orgId: OrgId,
  slug: string,
): Promise<ProjectWithStats> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectBySlug(orgId, slug),
    "Project",
    slug,
  );
  assertCan(actor, "project:read", projectResource(project));

  return {
    project,
    stats: await projectRepo.getProjectStats(orgId, project.id),
  };
}

export async function listProjects(
  actor: Actor,
  input: ListProjectsInput,
): Promise<Page<ProjectWithStats>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:read", orgResource(input.orgId));

  const page = await projectRepo.listProjects(input);

  const items = await Promise.all(
    page.items.map(async (project) => ({
      project,
      stats: await projectRepo.getProjectStats(input.orgId, project.id),
    })),
  );

  return { items, nextCursor: page.nextCursor, total: page.total };
}

/**
 * Slug preview used by both the create form and `createProject`, so what the
 * user sees while typing is what the row ends up with.
 */
export async function suggestProjectSlug(
  orgId: OrgId,
  name: string,
): Promise<string> {
  const taken = await projectRepo.listTakenProjectSlugs(orgId);
  return uniqueSlug(name, taken);
}

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  WebhookId,
} from "./common";
import type { Role } from "./member";
import type { ProjectVisibility } from "./project";

/**
 * The complete action vocabulary of `can()`. Every authorization decision in
 * Taskflow names one of these — there is no free-form string permission.
 */
export type PermissionAction =
  | "org:read"
  | "org:update"
  | "org:delete"
  | "org:manage_billing"
  | "org:manage_flags"
  | "member:read"
  | "member:invite"
  | "member:update_role"
  | "member:remove"
  | "project:create"
  | "project:read"
  | "project:update"
  | "project:archive"
  | "project:delete"
  | "issue:create"
  | "issue:read"
  | "issue:update"
  | "issue:assign"
  | "issue:archive"
  | "issue:delete"
  | "comment:create"
  | "comment:read"
  | "comment:update"
  | "comment:delete"
  | "activity:read"
  | "activity:export"
  | "notification:read"
  | "notification:manage"
  | "webhook:manage";

/**
 * The object a permission is asked about. Discriminated on `kind` so the
 * ownership rules inside `can()` can read the fields they need without casts.
 */
export type PermissionResource =
  | { readonly kind: "organization"; readonly orgId: OrgId }
  | { readonly kind: "billing"; readonly orgId: OrgId }
  | {
      readonly kind: "member";
      readonly orgId: OrgId;
      readonly memberId: MemberId;
      readonly targetUserId: UserId;
      readonly targetRole: Role;
    }
  | {
      readonly kind: "project";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly visibility: ProjectVisibility;
      readonly leadId: UserId | null;
    }
  | {
      readonly kind: "issue";
      readonly orgId: OrgId;
      readonly projectId: ProjectId;
      readonly issueId: IssueId;
      readonly authorId: UserId;
      readonly assigneeId: UserId | null;
    }
  | {
      readonly kind: "comment";
      readonly orgId: OrgId;
      readonly commentId: CommentId;
      readonly authorId: UserId;
    }
  | { readonly kind: "activity"; readonly orgId: OrgId }
  | { readonly kind: "notification"; readonly orgId: OrgId; readonly recipientId: UserId }
  | { readonly kind: "webhook"; readonly orgId: OrgId; readonly webhookId: WebhookId | null };

export type PermissionResourceKind = PermissionResource["kind"];

/** Verbose form of a decision, used by the settings UI to explain a denial. */
export interface PermissionDecision {
  readonly allowed: boolean;
  readonly action: PermissionAction;
  readonly resourceKind: PermissionResourceKind;
  readonly reason:
    | "granted_by_role"
    | "granted_by_ownership"
    | "granted_by_staff"
    | "denied_by_role"
    | "denied_cross_tenant"
    | "denied_unknown_action";
}
import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}

import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}

/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
