        userId: activeMember.userId,
        orgId: input.orgId,
        role: activeMember.role,
      },
      "project:update",
      projectResource(project),
    );
  }

  return requireFound(
    await projectRepo.changeProjectLead(input),
    "Project",
    input.projectId,
  );
}

